diff --git a/node/jsonl-summary/index.mjs b/node/jsonl-summary/index.mjs
index 9270e54..fb78008 100644
--- a/node/jsonl-summary/index.mjs
+++ b/node/jsonl-summary/index.mjs
@@ -1,3 +1,60 @@
 export function summarizeJsonl(text) {
-  return { runs: 0, passed: 0, failed: 0, costUsd: 0 };
+  const lines = text.split(/\r\n|\n/);
+
+  let runs = 0;
+  let passed = 0;
+  let failed = 0;
+  let costUsd = 0;
+
+  for (let i = 0; i < lines.length; i += 1) {
+    const line = lines[i];
+    const lineNumber = i + 1;
+
+    if (line.trim() === "") {
+      continue;
+    }
+
+    let record;
+    try {
+      record = JSON.parse(line);
+    } catch {
+      throw new Error(`Invalid JSON on line ${lineNumber}`);
+    }
+
+    if (
+      typeof record !== "object" ||
+      record === null ||
+      Array.isArray(record) ||
+      (record.status !== "pass" && record.status !== "fail")
+    ) {
+      throw new Error(`Invalid record on line ${lineNumber}`);
+    }
+
+    let cost = 0;
+    if (record.cost_usd !== undefined) {
+      if (
+        typeof record.cost_usd !== "number" ||
+        !Number.isFinite(record.cost_usd) ||
+        record.cost_usd < 0
+      ) {
+        throw new Error(`Invalid record on line ${lineNumber}`);
+      }
+      cost = record.cost_usd;
+    }
+
+    runs += 1;
+    if (record.status === "pass") {
+      passed += 1;
+    } else {
+      failed += 1;
+    }
+    costUsd += cost;
+  }
+
+  return {
+    runs,
+    passed,
+    failed,
+    costUsd: Math.round(costUsd * 100) / 100,
+  };
 }
